INSERT INTO roles(name) VALUES ('admin'),('super_admin');
INSERT INTO permissions(name) VALUES ('dashboard.view'),('collections.view'),('collections.create'),('collections.edit'),('collections.delete'),('subcollections.view'),('subcollections.create'),('subcollections.edit'),('subcollections.delete'),('products.view'),('products.create'),('products.edit'),('products.delete'),('applications.view'),('applications.create'),('applications.edit'),('applications.delete'),('media.view'),('media.upload'),('media.delete'),('homepage.manage'),('store.manage'),('contact_requests.view'),('contact_requests.manage'),('seo.manage'),('menus.manage'),('settings.manage'),('admins.view'),('admins.create'),('admins.edit'),('admins.disable'),('admins.password'),('logs.view'),('system.backup'),('system.maintenance');
INSERT INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r JOIN permissions p WHERE r.name='admin';
