INSERT INTO settings(setting_key,setting_value) VALUES ('site_name','PERLINA'),('site_description','Premium perde, tül, stor, zebra, jaluzi ve plise showroom deneyimi.'),('maintenance_mode','0');
INSERT INTO store(name,address,phone,whatsapp,email,working_hours,maps_url,directions_url,maps_embed,hero_image) VALUES ('PERLINA Showroom','Mağaza adresi yönetim panelinden güncellenebilir.','+90 555 111 22 33','+90 555 111 22 33','info@perlina.local','Pazartesi - Cumartesi 10:00 - 19:00','https://maps.google.com','https://maps.google.com','<iframe title="PERLINA Google Maps" src="https://maps.google.com" loading="lazy"></iframe>','/public/assets/images/hero.svg');
INSERT INTO collections(name,slug,short_description,long_description,cover_image,hero_image,featured,sort_order,seo_title,meta_description) VALUES ('Tül Perde','tul-perde','Işığı yumuşatan zarif dokular.','Modern ve klasik yaşam alanları için premium tül perde seçenekleri.','/public/assets/images/hero.svg','/public/assets/images/hero.svg',1,1,'Tül Perde Koleksiyonu','PERLINA premium tül perde koleksiyonu'),('Stor Perde','stor-perde','Fonksiyonel ve yalın stor çözümleri.','Mahremiyet ve ışık kontrolünü premium dokuyla birleştiren stor koleksiyonu.','/public/assets/images/hero.svg','/public/assets/images/hero.svg',1,2,'Stor Perde','Premium stor perde çözümleri');
INSERT INTO subcollections(collection_id,name,slug,description,image,featured,sort_order) SELECT id,'Modern','modern','Sade çizgiler ve güçlü dokular.','/public/assets/images/hero.svg',1,1 FROM collections WHERE slug='tul-perde';
INSERT INTO products(collection_id,subcollection_id,name,slug,short_description,long_description,main_image,featured,sort_order,seo_title,meta_description) SELECT c.id,s.id,'Luna Tül','luna-tul','Yumuşak ışık geçişli premium tül.','Luna Tül, showroomda ölçü ve uygulama danışmanlığıyla sunulan zarif bir pencere çözümüdür.','/public/assets/images/hero.svg',1,1,'Luna Tül','PERLINA Luna Tül ürün detayı' FROM collections c LEFT JOIN subcollections s ON s.collection_id=c.id WHERE c.slug='tul-perde' LIMIT 1;
INSERT INTO applications(title,slug,description,content,main_image,featured,sort_order) VALUES ('Salon Uygulaması','salon-uygulamasi','Geniş salonlarda katmanlı tül ve fon perde kullanımı.','PERLINA ekibi mekân ışığı, ölçü ve kullanım alışkanlıklarına göre uygulama planlar.','/public/assets/images/hero.svg',1,1);
